describe('ZIP Code Auto-Formatting Field', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should auto-format ZIP code as user types', () => {
    // Intercept the API call for validation
    cy.intercept('POST', '/api/validate-zip').as('validateZip');

    // Get the ZIP code input field
    cy.get('[data-testid="zip-input"]').should('be.visible');

    // Type a partial ZIP code
    cy.get('[data-testid="zip-input"]').type('1234');

    // Verify the auto-formatted ZIP code appears
    cy.get('[data-testid="zip-input"]').should('have.value', '1234');

    // Type more digits
    cy.get('[data-testid="zip-input"]').type('56789');

    // Verify the auto-formatted ZIP code is complete
    cy.get('[data-testid="zip-input"]').should('have.value', '123456789');

    // Verify the input is still editable
    cy.get('[data-testid="zip-input"]').type('1234567890');

    // Verify the auto-formatting still works
    cy.get('[data-testid="zip-input"]').should('have.value', '1234567890');

    // Verify the validation API is called
    cy.wait('@validateZip').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });

  it('should handle invalid ZIP code format and display error message', () => {
    // Intercept the API call for validation
    cy.intercept('POST', '/api/validate-zip').as('validateZip');

    // Get the ZIP code input field
    cy.get('[data-testid="zip-input"]').should('be.visible');

    // Type an invalid ZIP code format
    cy.get('[data-testid="zip-input"]').type('abc123');

    // Verify the auto-formatted ZIP code is not complete
    cy.get('[data-testid="zip-input"]').should('have.value', 'abc123');

    // Verify the validation API is called
    cy.wait('@validateZip').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });

    // Verify error message is displayed
    cy.get('[data-testid="zip-error-message"]').should('be.visible');
    cy.get('[data-testid="zip-error-message"]').should('contain', 'Invalid ZIP code format');

    // Verify the input still allows further typing
    cy.get('[data-testid="zip-input"]').type('1234567890');

    // Verify the error message disappears
    cy.get('[data-testid="zip-error-message"]').should('not.exist');
  });
});
